SELECT MONTH(opened_date) opened_month, CASE WHEN sqft >= 13640 THEN 'high' WHEN sqft >= 6569 THEN 'mid' ELSE 'low' END sqft_bucket, COUNT(DISTINCT sqft) unique_citys, COUNT(CASE WHEN city = 'London' THEN 1 END) london_count, ROUND((100 * SUM(CASE WHEN city = 'London' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_london FROM stores WHERE (store_name LIKE '%Downtow%' AND city IN ('New York', 'Bangkok')) OR store_name LIKE '%Cen%' GROUP BY MONTH(opened_date), CASE WHEN sqft >= 13640 THEN 'high' WHEN sqft >= 6569 THEN 'mid' ELSE 'low' END HAVING unique_citys < 5;
